<div id="result"></div>

<script>
const target = `{{[Sg] Nominativ}}`;

const fields = {
    "Nom. Sg.": `{{[Sg] Nominativ}}`,
    "Nom. Pl.": `{{[Pl] Nominativ}}`,
    "Gen. Sg.": `{{[Sg] Genitiv}}`,
    "Gen. Pl.": `{{[Pl] Genitiv}}`,
    "Dat. Sg.": `{{[Sg] Dativ}}`,
    "Dat. Pl.": `{{[Pl] Dativ}}`,
    "Akk. Sg.": `{{[Sg] Akkusativ}}`,
    "Akk. Pl.": `{{[Pl] Akkusativ}}`,
    "Abl. Sg.": `{{[Sg] Ablativ}}`,
    "Abl. Pl.": `{{[Pl] Ablativ}}`
};

const matches = Object.entries(fields)
    .filter(([name, value]) => value === target);

const html = matches
    .map(([name, value]) => `<li>${name}</li>`)
    .join("");

document.getElementById("result").innerHTML = `<ul>${html}</ul>`;
</script>

